import{_ as l,a,c as r,ac as i}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"English 背单词技巧","description":"词汇分类、重复复习、卡片与实际应用方法","frontmatter":{"title":"English 背单词技巧","description":"English 背单词技巧","sources":[{"repository":"jekyall_blog","file":"_posts/Cc/English/2023-05-17-vocabulary.md","date":"Sat May 16 2020 11:12:55 GMT+0800 (中国标准时间)"}],"showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","summary":"词汇分类、重复复习、卡片与实际应用方法","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":false,"next":{"text":"英语：错因记录与能力回看","link":"/life/english/review/reflection"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"英语：错因记录与能力回看","link":"/life/english/review/reflection"}},"headers":[],"relativePath":"life/english/review/vocabulary.md","filePath":"life/english/review/vocabulary.md"}'),n={name:"life/english/review/vocabulary.md"};function o(t,e,s,c,g,p){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="english-背单词技巧" tabindex="-1">English 背单词技巧 <a class="header-anchor" href="#english-背单词技巧" aria-label="Permalink to &quot;English 背单词技巧&quot;">​</a></h1><h2 id="背单词技巧" tabindex="-1">背单词技巧 <a class="header-anchor" href="#背单词技巧" aria-label="Permalink to &quot;背单词技巧&quot;">​</a></h2><ol><li>利用记忆法：将单词与形象的图像、故事或关联起来，可以更容易地记忆单词。例如，把“banana”（香蕉）和一个画着笑脸的香蕉联系起来。这种记忆方法被称为视觉记忆法，它能够帮助您将单词转化成可视的形象，使其更容易记忆。另外还有听觉记忆法和动作记忆法等</li><li>分类记忆：将单词按主题分类，如食品、动物、家庭等。这样可以帮助您将单词组织在一起，方便记忆。此外，如果您正在学习某个特定领域的英语词汇，例如商务、医疗或科技，可以将单词按该领域进行分类，以便更好地理解和使用这些单词</li><li>多次重复：多次重复单词是记忆的关键。反复阅读单词列表、写下单词、朗读单词，都可以帮助您记忆单词。您可以将单词写在卡片上，每天花几分钟时间进行复习，或者在学习过程中使用闪卡，不断重复单词，直到您能够熟练掌握这些单词</li><li>制作卡片：写下单词和定义，以及相关的图片或例句，制成卡片，随时随地进行复习。在每张卡片上，您可以写下该单词的释义、近义词、反义词、用法等信息，以便更好地记忆这些单词。此外，您还可以在卡片上添加关联的图像或例句，以帮助您更好地理解单词的意思</li><li>应用到实际生活中：将新学习的单词应用到日常生活中，如在对话中使用、写邮件或文章时使用，可以加深记忆。通过使用这些单词来表达自己的思想和意见，您可以更好地理解它们的含义和用法，并在实践中更熟练地应用它们</li><li>使用在线资源：许多网站和应用程序可以提供背单词的帮助，包括 Quizlet、Anki 和 Memrise 等。这些资源可以根据您的学习需求和兴趣为您提供各种类型的单词列表和记忆方法。此外，这些资源还可以跟踪您的进度和提供反馈，以帮助您更好地记忆和掌握单词</li></ol><h2 id="网站和书籍" tabindex="-1">网站和书籍 <a class="header-anchor" href="#网站和书籍" aria-label="Permalink to &quot;网站和书籍&quot;">​</a></h2><ol><li><a href="https://quizlet.com/" target="_blank" rel="noopener noreferrer">Quizlet</a>：Quizlet 是一个在线学习平台，可以让用户创建和分享各种类型的学习资料，包括单词列表、闪卡、测试等。</li><li><a href="https://apps.ankiweb.net/" target="_blank" rel="noopener noreferrer">Anki</a>：Anki 是一款基于间隔重复记忆算法的开源软件，可以帮助用户更有效地记忆单词、概念、公式等内容。</li><li><a href="https://www.memrise.com/" target="_blank" rel="noopener noreferrer">Memrise</a>：Memrise 是一个多语言学习平台，可以提供各种类型的学习课程和游戏，包括语言、科学、文化等领域。</li><li><a href="https://www.duolingo.com/" target="_blank" rel="noopener noreferrer">Duolingo</a>：Duolingo 是一款免费的语言学习应用程序，可以帮助用户学习多种语言，包括英语、西班牙语、法语等。</li><li>Cambridge English Vocabulary in Use 系列（<a href="https://www.cambridge.org/us/cambridgeenglish/catalog/vocabulary-and-grammar/vocabulary-use%EF%BC%89%EF%BC%9ACambridge" target="_blank" rel="noopener noreferrer">https://www.cambridge.org/us/cambridgeenglish/catalog/vocabulary-and-grammar/vocabulary-use）：Cambridge</a> English Vocabulary in Use 系列是由剑桥大学出版社出版的一套词汇教材，覆盖从初级到高级的各个层次，可以帮助学习者系统地掌握英语词汇。</li><li>Oxford Word Skills 系列（<a href="https://elt.oup.com/catalogue/items/global/skills/vocabulary/oxford_word_skills/?cc=cn&amp;selLanguage=en%EF%BC%89%EF%BC%9AOxford" target="_blank" rel="noopener noreferrer">https://elt.oup.com/catalogue/items/global/skills/vocabulary/oxford_word_skills/?cc=cn&amp;selLanguage=en）：Oxford</a> Word Skills 系列是由牛津大学出版社出版的一套词汇教材，包括基础、中级和高级三个层次，针对不同水平的学习者提供了丰富的单词练习和解释。</li></ol><h2 id="app" tabindex="-1">App <a class="header-anchor" href="#app" aria-label="Permalink to &quot;App&quot;">​</a></h2><ol><li>扇贝单词：扇贝单词是一款功能齐全的背单词 App，提供海量单词库和各种学习模式，包括闪卡、听力、口语等。</li><li>有道词典：有道词典是一款广受欢迎的翻译和词典 App，除了提供单词释义和例句外，还可以通过朗读、发音练习等方式帮助用户记忆单词。</li><li>单词背诵机：单词背诵机是一款专门针对英语四级和六级考试设计的背单词 App，提供大量真实考试题目以及各种背单词功能。</li><li>知米背单词：知米背单词是一款注重用户体验的背单词 App，提供精美的 UI 界面和多种学习模式，包括闪卡、填空、选择等。</li><li>喜马拉雅背单词：喜马拉雅背单词是一款通过听力练习帮助用户记忆单词的 App，提供大量英语原版音频材料和智能化的练习模式。</li></ol>',7)])])}const u=l(n,[["render",o]]);export{h as __pageData,u as default};
